'use strict';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const invoke=window.__TAURI__?.core?.invoke;
const slowCommandLogs=new Map();
const call=async(command,payload={})=>{if(!invoke)throw 'Abra pelo programa BatCaverna.';const started=performance.now();try{return await invoke(command,payload)}catch(error){if(command!=='client_log'&&command!=='cover_image')invoke('client_log',{input:{level:'ERROR',stage:'COMMAND_FAILURE',message:`${command}${payload.input?.op?"/"+payload.input.op:""}: ${failure(error)}`}}).catch(()=>{});throw error}finally{const elapsed=Math.round(performance.now()-started),now=Date.now(),last=slowCommandLogs.get(command)||0;if(command!=='client_log'&&elapsed>=700&&now-last>=60000){slowCommandLogs.set(command,now);invoke('client_log',{input:{level:'INFO',stage:'SLOW_COMMAND',message:`${command}: ${elapsed} ms`}}).catch(()=>{})}}};
function normalizeGenres(value){return [...new Set((Array.isArray(value)?value:String(value||'').split(/[•,|]/)).map(g=>typeof g==='string'?g.trim():String(g?.name||g?.description||'').trim()).filter(Boolean))]}
const readCache=new Map();
function cachedRead(scope,input,ttl,load){
 const key=`${typeof state==='undefined'?'':state.userId||''}|${scope}|${JSON.stringify(input)}`,hit=readCache.get(key);
 if(hit&&hit.expires>Date.now())return hit.promise;
 const promise=load();readCache.set(key,{promise,expires:Date.now()+ttl});
 promise.catch(()=>{if(readCache.get(key)?.promise===promise)readCache.delete(key)});
 if(readCache.size>200)for(const[k,v]of readCache)if(v.expires<=Date.now())readCache.delete(k);
 return promise;
}
const api=Object.freeze({
 state:()=>call('app_state'),login:credentials=>call('login',{credentials}),register:input=>call('register',{input}),recover:email=>call('recover_password',{email}),verifyEmail:input=>call('verify_email_proof',{input}),resendConfirmation:email=>call('resend_confirmation',{email}),logout:()=>call('logout'),
 checkForUpdates:()=>call('check_for_updates'),installUpdate:version=>call('install_update',{version}),
 dashboard:()=>call('dashboard'),stats:()=>call('journey_stats'),profile:userId=>call('profile',{userId:userId||null}),updateProfile:input=>call('update_profile',{input}),changePassword:input=>call('change_password',{input}),
 library:category=>call('library',{category}),saveItem:item=>call('save_item',{item:{...item,...('generos' in item?{generos:normalizeGenres(item.generos)}:{})}}),deleteItem:id=>call('delete_item',{id:String(id)}),
 feed:()=>call('feed'),socialMeta:()=>call('social_meta'),publish:input=>call('publish',{input}),uploadMedia:input=>call('upload_media',{input}),mediaUrl:url=>call('media_url',{url}),
 toggleLike:input=>call('toggle_like',{input}),addComment:input=>call('add_comment',{input}),friends:()=>call('friends'),searchPeople:query=>call('search_people',{query}),invite:userId=>call('send_friend_invite',{input:{userId}}),
 messages:friendId=>call('chat_messages',{friendId}),sendMessage:input=>call('send_message',{input}),notifications:()=>call('notifications'),markNotificationsRead:()=>call('mark_notifications_read'),respondInvite:input=>call('respond_friend_invite',{input}),
 catalog:input=>cachedRead('catalog',input,300000,()=>call('catalog',{input})),coverImage:url=>call('cover_image',{url}),uploadProfile:input=>call('upload_profile_image',{input}),bright:input=>['gratis','jogos','raPerfil','raJogos','raConquistas'].includes(input?.op)?cachedRead('bright',input,120000,()=>call('bright_api',{input})):call('bright_api',{input}),open:url=>call('open_external',{url})
});
const state={current:'home',profile:null,userId:'',email:'',version:'',libraryCategory:'jogos',libraryStatus:'all',libraryQuery:'',librarySort:'recent',libraryRows:[],chatFriend:null,profileUser:null,settingsTab:'account',discoverTab:'free',uploadFiles:[]};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const date=v=>{try{return new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v))}catch{return''}};
const failure=e=>typeof e==='string'&&e.trim()?e:e?.message||'Não foi possível concluir. Tente novamente.';
const failureMessage=failure;
const validImage=u=>/^https:\/\//i.test(String(u||''))?esc(u):'brand.jpg';
function toast(message){const n=$('#toast');n.textContent=message;n.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.hidden=true,3500)}
function loading(){ $('#content').innerHTML='<div class="loading"><span class="spinner"></span>Carregando…</div>' }
