function showLogin(){ $('#appShell').hidden=true;$('#loginScreen').hidden=false;setAuth('login');document.documentElement.classList.remove('booting') }
async function showApp(){ $('#appVersion').textContent=`v${state.version}`;await navigate('home');$('#loginScreen').hidden=true;$('#appShell').hidden=false;document.documentElement.classList.remove('booting') }
function applyPrefs(){const p=JSON.parse(localStorage.getItem('bc-desktop-prefs')||'{}');document.body.classList.toggle('compact',!!p.compact);document.body.classList.toggle('no-animations',!!p.noAnimations)}
function savePref(key,value){if(['compact','noAnimations'].includes(key)&&state.userId&&window.batcavernaLayoutSync){const sync=window.batcavernaLayoutSync;sync.save({...sync.get(),[key]:value});return;}const p=JSON.parse(localStorage.getItem('bc-desktop-prefs')||'{}');p[key]=value;localStorage.setItem('bc-desktop-prefs',JSON.stringify(p));applyPrefs()}

async function signed(value){const url=String(value||'').trim();if(!url)return 'brand.jpg';if(/^data:image\//i.test(url))return url;try{return await api.mediaUrl(url)}catch{return /^https:\/\//i.test(url)?url:'brand.jpg'}}
const requiresMediaSigning=url=>!/^https:\/\//i.test(url)||/\.supabase\.co\/storage\/v1\/object\/public\//i.test(url);
function hydrateMedia(root=document){for(const n of root.querySelectorAll('[data-private-src]')){const url=String(n.dataset.privateSrc||'').trim();n.removeAttribute('data-private-src');if(!url){n.src='brand.jpg';continue}void (requiresMediaSigning(url)?signed(url):Promise.resolve(url)).then(src=>{if(n.isConnected)n.src=src}).catch(()=>{if(n.isConnected)n.src='brand.jpg'})}return Promise.resolve()}
function applyBrand(profile){const logo=profile?.fundo?.logo;if(logo&&(/^(https:|data:image)/i.test(logo))){$$('.logo img,.brand-mark img,.welcome img').forEach(n=>{void signed(logo).then(src=>{if(n.isConnected)n.src=src}).catch(()=>{if(n.isConnected)n.src='brand.jpg'})})}}
async function navigate(view){const request=state.navigationSequence=(state.navigationSequence||0)+1,start=performance.now();state.current=view;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.discoverKind?view==='discover'&&b.dataset.discoverKind===state.discoverTab:(view==='library'?(b.dataset.collection===state.libraryCategory||b.dataset.view==='library'&&state.libraryCategory==='jogos'):b.dataset.view===view)));loading();try{if(view==='home')await renderHome();if(view==='library')await renderLibrary();if(view==='discover')await renderDiscover();if(view==='social')await renderSocial();if(view==='chat')await renderChat();if(view==='friends')await renderFriends();if(view==='notifications')await renderNotifications();if(view==='profile')await renderProfile(state.profileUser);if(view==='settings')await renderSettings()}catch(e){if(request===state.navigationSequence)errorCard(e)}finally{const elapsed=Math.round(performance.now()-start);if(request===state.navigationSequence&&elapsed>=700&&invoke)invoke('client_log',{input:{level:'INFO',stage:'SLOW_VIEW',message:`${view}${view==='library'?` (${state.libraryCategory})`:''}: ${elapsed} ms`}}).catch(()=>{})}}

function normalizedStatus(value){const v=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/platina|100%/.test(v))return 'platinum';if(/zerado|finaliz|conclu|assistido/.test(v))return 'finished';if(/favorit/.test(v))return 'favorite';if(/progresso|jogando|assistindo/.test(v))return 'progress';if(/abandon|desist/.test(v))return 'abandoned';if(/paus/.test(v))return 'paused';if(/steam/.test(v))return 'steam';return 'backlog'}
function coverUrl(value){let u=String(value||'').trim();if(u.startsWith('//'))u='https:'+u;if(u.startsWith('http://'))u='https://'+u.slice(7);if(/^\/[^/]+\.(jpg|png|webp)$/i.test(u))u='https://image.tmdb.org/t/p/w500'+u;return /^https:\/\//i.test(u)?u:''}
function isPinnedCover(value){return /(?:^|\.)steamgriddb\.com\/|supabase\.co\/storage\//i.test(coverUrl(value))}
function mediaCard(item){return `<article class="media-card" data-item-id="${esc(item.id)}"><div class="cover-wrap"><img loading="lazy" src="brand.jpg" data-cover="${esc(coverUrl(item.capa))}" data-cover-name="${esc(item.nome)}" data-cover-game="${item.categoria==='jogos'||!item.categoria?'1':'0'}" alt="Capa de ${esc(item.nome)}"><span>${esc(item.status||'Na biblioteca')}</span></div><div class="body"><h3>${esc(item.nome)}</h3><small>${esc(item.plataforma||item.onde||item.tipo||'BatCaverna')}</small></div></article>`}
const coverCache=new Map();let coverActive=0;const coverPending=[];
function queueCover(work){return new Promise((resolve,reject)=>{coverPending.push({work,resolve,reject});pumpCovers()})}
function pumpCovers(){while(coverActive<6&&coverPending.length){const task=coverPending.shift();coverActive++;Promise.resolve().then(task.work).then(task.resolve,task.reject).finally(()=>{coverActive--;pumpCovers()})}}
function hydrateCovers(root){for(const n of root.querySelectorAll('[data-cover]')){const url=n.dataset.cover,name=n.dataset.coverName,game=n.dataset.coverGame==='1';n.removeAttribute('data-cover');n.src=url||'brand.jpg';n.onerror=()=>{n.onerror=null;queueCover(async()=>{if(url){try{return await api.coverImage(await signed(url))}catch{}}if(game){try{const d=await api.bright({op:'capas',nomes:[name]});const alt=d.capas?.[0];if(alt)return await api.coverImage(alt)}catch{}}throw Error('Capa indisponível')}).then(src=>{if(n.isConnected)n.src=src}).catch(()=>{if(n.isConnected){n.src='brand.jpg';n.title='Capa indisponível. Use Buscar capas no editor.'}})}}}
function playtimeHours(value){const hours=Number(value);return Number.isFinite(hours)&&hours>=0?hours:0;}
function formatPlaytime(value){return playtimeHours(value).toLocaleString('pt-BR',{maximumFractionDigits:1});}
function statsFromRows(rows){const months=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-11+i);return {mes:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,jogos:0,midias:0}});const totals={total:rows.length,concluidos:0,horas:0,jogos:0,filmes:0,series:0,animes:0,sem_data:0,months};for(const r of rows){const game=r.categoria==='jogos',kind=game?'jogos':/anime|🍥/i.test(r.tipo||'')?'animes':/serie|série|📺/i.test(r.tipo||'')?'series':'filmes';totals[kind]++;if(game)totals.horas+=playtimeHours(r.horas);if(['finished','platinum','favorite'].includes(normalizedStatus(r.status))){totals.concluidos++;const m=String(r.data||'').slice(0,7);if(!/^\d{4}-\d{2}$/.test(m))totals.sem_data++;const month=months.find(x=>x.mes===m);if(month)month[game?'jogos':'midias']++}}return totals}
async function loadStats(){try{const r=await api.stats(),s=Array.isArray(r)?r[0]:r;if(s&&Array.isArray(s.months))return s}catch{}const sets=await Promise.all(['jogos','filmes','series','animes'].map(c=>api.library(c)));return statsFromRows(sets.flat())}
function chart(stats){const months=stats?.months||[],max=Math.max(1,...months.map(m=>(Number(m.jogos)||0)+(Number(m.midias)||0))),pct=stats.total?Math.round(stats.concluidos/stats.total*100):0;return `<section class="charts"><article class="chart-card"><h3>Conclusões por mês</h3><p class="muted">Últimos 12 meses · pela data de conclusão</p><div class="chart-bars">${months.map(m=>{const games=Number(m.jogos)||0,media=Number(m.midias)||0;return `<div class="month-column" title="${esc(m.mes)}: ${games} jogos e ${media} mídias"><div class="month-stack"><i class="games-bar" style="height:${games/max*100}%"></i><i class="media-bar" style="height:${media/max*100}%"></i></div><small>${esc(m.mes.slice(5)+'/'+m.mes.slice(2,4))}</small><b>${games+media}</b></div>`}).join('')}</div><p class="chart-legend">🟣 Jogos &nbsp; 🔴 Filmes, séries e animes</p></article><article class="chart-card"><h3>Taxa de conclusão</h3><div class="donut" style="--pct:${pct}%" data-label="${pct}%"></div><p class="muted">${Number(stats.concluidos)||0} de ${Number(stats.total)||0} títulos concluídos</p><p>${Number(stats.horas||0).toLocaleString('pt-BR',{maximumFractionDigits:1})} horas jogadas registradas</p></article><article class="chart-card"><h3>Sua coleção</h3>${[['jogos','Jogos'],['filmes','Filmes'],['series','Séries'],['animes','Animes']].map(([k,l])=>`<div class="distribution"><span>${l}</span><progress max="${Math.max(1,stats.total||0)}" value="${Number(stats[k])||0}" aria-label="${l}"></progress><b>${Number(stats[k])||0}</b></div>`).join('')}</article><article class="chart-card"><h3>Detalhes mensais</h3><div class="stats-table-wrap"><table class="stats-table"><thead><tr><th>Mês</th><th>Jogos</th><th>Mídias</th><th>Total</th></tr></thead><tbody>${months.map(m=>`<tr><td>${esc(m.mes.slice(5)+'/'+m.mes.slice(0,4))}</td><td>${Number(m.jogos)||0}</td><td>${Number(m.midias)||0}</td><td>${(Number(m.jogos)||0)+(Number(m.midias)||0)}</td></tr>`).join('')}</tbody></table></div><p class="muted">${Number(stats.sem_data)||0} concluídos sem data. Horas representam o total atual, sem estimativa mensal.</p></article></section>`}
async function renderHome(){setPage('Início','SUA BATCAVERNA');const [data,statsResult]=await Promise.all([api.dashboard(),loadStats().catch(e=>({error:failure(e)}))]);state.profile=data.profile;state.userId=data.profile.id||state.userId;state.email=data.email||state.email;applyBrand(data.profile);$('#accountName').textContent=data.profile.nome||data.profile.slug||'Minha conta';$('#accountStatus').textContent=statusLabels[data.profile.status_personalizado]||'Online';$('#accountAvatar').dataset.privateSrc=data.profile.avatar_url||'';hydrateMedia($('.topbar'));$('#navUnread').hidden=!data.counts.unread;const stats=statsResult?.error?null:statsResult;$('#content').innerHTML=`<section class="welcome"><div><span>OLÁ, ${esc((data.profile.nome||'CLT').split(' ')[0].toUpperCase())}</span><h2>O que vamos acompanhar hoje?</h2><p>Seus títulos, amigos e conversas reunidos aqui.</p></div><img src="brand.jpg" alt=""></section><section class="stats">${[['Jogos',data.counts.totalGames],['Jogando',data.counts.playing],['Concluídos',data.counts.finished],['Filmes e séries',data.counts.totalMedia],['Não lidas',data.counts.unread]].map(([l,v])=>`<article class="stat"><small>${l}</small><strong>${v}</strong></article>`).join('')}</section>${stats?chart(stats):`<div class="error-card">Estatísticas indisponíveis: ${esc(statsResult?.error||'Tente novamente.')}</div>`}<div class="section-head"><div><h2>Biblioteca recente</h2><p>Continue de onde parou.</p></div><button class="secondary" data-go="library">Ver biblioteca</button></div><section class="grid">${data.recent.map(mediaCard).join('')||'<div class="empty">Nenhum título cadastrado.</div>'}</section><div class="section-head"><div><h2>Últimas atualizações</h2></div></div><section class="updates">${data.updates.map(x=>`<div class="update"><div><strong>${esc(x.nome)}</strong><div class="muted">${esc(x.status||x.categoria)}</div></div><small>${date(x.updated_at)}</small></div>`).join('')||'<div class="empty">Ainda não há atualizações.</div>'}</section>`;hydrateCovers($('#content'));applyBrand(data.profile);$('[data-go="library"]')?.addEventListener('click',()=>navigate('library'))}

function categoryInfo(k){return k==='jogos'?{category:'jogos',type:'',label:'Jogo'}:{category:'filmes',type:k==='filmes'?'filme':k==='series'?'serie':'anime',label:k==='filmes'?'Filme':k==='series'?'Série':'Anime'}}
function statusGroups(game){return game?[['progress','Em progresso'],['backlog','Backlog'],['finished','Zerados'],['platinum','Platinados'],['paused','Pausados'],['abandoned','Abandonados'],['steam','Biblioteca Steam'],['favorite','Favoritos']]:[['progress','Assistindo'],['backlog','Para assistir'],['finished','Concluídos'],['favorite','Favoritos'],['paused','Pausados'],['abandoned','Abandonados']]}
async function renderLibrary(){setPage('Biblioteca','MINHA COLEÇÃO');state.libraryRows=await api.library(state.libraryCategory);const cats=[['jogos','Jogos'],['filmes','Filmes'],['series','Séries'],['animes','Animes']];$('#content').innerHTML=`<div class="library-toolbar"><div class="tabs">${cats.map(([k,l])=>`<button data-category="${k}" class="${k===state.libraryCategory?'active':''}">${l}</button>`).join('')}</div><button id="addItem" class="primary">+ Adicionar</button></div><div class="library-controls"><input id="librarySearch" type="search" placeholder="Buscar na biblioteca" value="${esc(state.libraryQuery)}"><select id="librarySort" aria-label="Ordenar"><option value="recent">Atualizados recentemente</option><option value="name">Nome A–Z</option><option value="rating">Maior nota</option><option value="hours">Mais horas jogadas</option></select></div><nav id="statusTabs" class="tabs status-tabs"></nav><div id="libraryGroups"></div>`;$$('[data-category]').forEach(b=>b.onclick=()=>{state.libraryCategory=b.dataset.category;state.libraryStatus='all';renderLibrary().catch(errorCard)});$('#addItem').onclick=()=>openItemEditor(null);$('#librarySearch').oninput=e=>{state.libraryQuery=e.target.value;drawLibrary()};$('#librarySort').value=state.librarySort;$('#librarySort').onchange=e=>{state.librarySort=e.target.value;drawLibrary()};drawLibrary()}
function drawLibrary(){const rows=state.libraryRows,groups=statusGroups(state.libraryCategory==='jogos');$('#statusTabs').innerHTML=[['all','Todos'],...groups].map(([k,l])=>`<button data-status="${k}" class="${state.libraryStatus===k?'active':''}">${l} <b>${k==='all'?rows.length:rows.filter(x=>normalizedStatus(x.status)===k).length}</b></button>`).join('');$$('[data-status]').forEach(b=>b.onclick=()=>{state.libraryStatus=b.dataset.status;drawLibrary()});const filtered=rows.filter(x=>String(x.nome).toLocaleLowerCase('pt-BR').includes(state.libraryQuery.toLocaleLowerCase('pt-BR'))).sort((a,b)=>state.librarySort==='name'?String(a.nome).localeCompare(String(b.nome),'pt-BR'):state.librarySort==='rating'?(Number(b.nota)||0)-(Number(a.nota)||0):state.librarySort==='hours'?(Number(b.horas)||0)-(Number(a.horas)||0):String(b.updated_at||'').localeCompare(String(a.updated_at||'')));let html='';for(const [k,l] of groups){if(state.libraryStatus!=='all'&&state.libraryStatus!==k)continue;const items=filtered.filter(x=>normalizedStatus(x.status)===k);if(items.length)html+=`<section class="library-section"><div class="section-head"><h2>${l} <small class="muted">${items.length}</small></h2></div><div class="grid">${items.map(mediaCard).join('')}</div></section>`}$('#libraryGroups').innerHTML=html||'<div class="empty">Nenhum título encontrado neste status.</div>';$('#libraryGroups').querySelectorAll('[data-item-id]').forEach(c=>c.onclick=()=>openItemEditor(rows.find(x=>String(x.id)===c.dataset.itemId)));hydrateCovers($('#libraryGroups'))}
function selectOptions(values,current){return [...new Set([current,...values].filter(Boolean))].map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function popup(content,cls=''){const overlay=document.createElement('div');overlay.className='editor-overlay';overlay.innerHTML=`<section class="editor ${cls}">${content}</section>`;document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.onclick=event=>{if(event.target===overlay)close()};overlay.querySelectorAll('[data-close]').forEach(button=>button.onclick=close);overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close()});return overlay}
function openItemEditor(item){const info=categoryInfo(state.libraryCategory),row=item||{},game=info.category==='jogos',statuses=game?['📌 Backlog','🎮 Em Progresso','✅ Zerado','🏆 100% (Platina)','⏸️ Pausado','❌ Abandonado','🟦 Biblioteca Steam']:['⏳ Para Assistir','▶️ Assistindo','✅ Concluído','⭐ Favorito','⏸️ Pausado','❌ Abandonado'];const o=document.createElement('div');o.className='editor-overlay';o.innerHTML=`<form class="editor"><header><div><small>${item?'EDITAR':'NOVO'} ${info.label.toUpperCase()}</small><h2>${item?esc(item.nome):`Adicionar ${info.label.toLowerCase()}`}</h2></div><button type="button" class="icon-button" data-close>×</button></header><section class="catalog-search"><label>Buscar ${game?'na IGDB':info.type==='anime'?'animes no AniList ou TMDB':'no TMDB'}<div class="search-row"><input id="catalogQuery" type="search" placeholder="Nome do título" value="${esc(row.nome||'')}">${info.type==='anime'?'<select id="animeProvider" aria-label="Catálogo de animes"><option value="anilist">AniList</option><option value="tmdb">TMDB</option></select>':''}<button type="button" class="secondary" id="catalogSearch">Buscar</button></div></label><p id="catalogMessage" role="status"></p><div id="catalogResults" class="catalog-results"></div></section><div class="editor-grid"><label class="wide">Nome<input name="nome" required maxlength="180" value="${esc(row.nome||'')}"></label><label>Status<select name="status">${selectOptions(statuses,row.status||statuses[0])}</select></label>${game?`<label>Plataforma<select name="plataforma">${selectOptions(['💻 PC','🎮 PlayStation 5','🎮 PlayStation 4','🎮 PlayStation 3','🟩 Xbox Series','🟩 Xbox One','🟩 Xbox 360','🕹️ Switch','🎮 Steam Deck','🍎 Mac','🐧 Linux'],row.plataforma||'💻 PC')}</select></label><label>Loja<select name="loja">${selectOptions(['Steam','Epic Games','GOG','Ubisoft Connect','EA App','Battle.net','Xbox Game Pass','PlayStation Store','Nintendo eShop','Outra'],row.loja||'Steam')}</select></label><label>Horas jogadas<input name="horas" type="number" min="0" step="any" value="${esc(row.horas||'')}"></label>`:`<label>Onde assistir<select name="onde">${selectOptions(['Não informado','Netflix','Prime Video','Disney+','Max','Apple TV+','Crunchyroll','Globoplay','YouTube','Cinema','Outro'],row.onde||'Não informado')}</select></label><input type="hidden" name="tipo" value="${esc(row.tipo||info.type)}">`}<label>Ano<input name="ano" type="number" min="1900" max="2200" value="${esc(row.ano||'')}"></label><label>Minha nota<select name="nota">${selectOptions(['Sem avaliação','💎 Lenda (GOTY)','⭐⭐⭐⭐⭐ Obra-prima','⭐⭐⭐⭐½ Excelente','⭐⭐⭐⭐ Muito bom','⭐⭐⭐½ Bom','⭐⭐⭐ Ok','⭐⭐ Fraco','⭐ Ruim','🤔 A considerar'],String(row.nota??'Sem avaliação'))}</select></label><label>Data de conclusão<input name="data" type="date" value="${esc(String(row.data||'').slice(0,10))}"></label><label class="wide">Gêneros<input name="generos" value="${esc(normalizeGenres(row.generos).join(' • '))}"></label><label class="wide">URL da capa<div class="search-row"><input name="capa" type="url" value="${esc(coverUrl(row.capa))}">${game?'<select id="coverOrientation" aria-label="Formato da capa"><option value="poster">Vertical</option><option value="landscape">Horizontal</option></select><button type="button" class="secondary" id="searchCover">SteamGridDB</button>':''}</div></label><div class="wide cover-choice"><img id="itemCoverPreview" src="${validImage(row.capa)}" alt="Prévia da capa"><p id="catalogDescription" class="muted"></p></div><label class="wide">Meu comentário<textarea name="review" maxlength="2000">${esc(row.review||'')}</textarea></label></div><footer>${item?'<button type="button" class="danger" data-delete>Excluir</button>':'<span></span>'}<div><button type="button" class="secondary" data-close>Cancelar</button><button class="primary">Salvar</button></div></footer><p class="form-error"></p></form>`;document.body.appendChild(o);const f=o.querySelector('form'),close=()=>o.remove();f.addEventListener('input',e=>{if(e.target.matches('input[type=number]'))e.target.dataset.numericTouched='1'});o.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);o.onclick=e=>{if(e.target===o)close()};const search=o.querySelector('#catalogSearch');search.onclick=()=>searchCatalog(f,info);o.querySelector('#catalogQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search.click()}};f.elements.capa.oninput=()=>o.querySelector('#itemCoverPreview').src=validImage(f.elements.capa.value);o.querySelector('#searchCover')?.addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;try{const input={op:'capaOpcoes',nomes:[f.elements.nome.value],format:f.querySelector('#coverOrientation').value};if(row.steam_appid)input.appids=[Number(row.steam_appid)];const d=await api.bright(input),options=d.opcoes||[];if(!options.length)throw Error('Nenhuma capa correspondente foi encontrada no SteamGridDB.');const picker=popup(`<button class="detail-close icon-button" data-close aria-label="Fechar">×</button><h2>Escolher capa ${input.format==='poster'?'vertical':'horizontal'}</h2><p class="muted">Imagens encontradas para ${esc(f.elements.nome.value)}. Selecione a capa oficial que deseja usar.</p><div class="cover-picker-grid">${options.map((x,i)=>`<button type="button" data-cover-option="${i}"><img src="${esc(x.url)}" alt="Opção ${i+1}"><small>${x.width} × ${x.height}</small></button>`).join('')}</div>`,'cover-picker');picker.querySelector('[data-close]').onclick=()=>picker.remove();picker.querySelectorAll('[data-cover-option]').forEach(option=>option.onclick=async()=>{const chosen=options[Number(option.dataset.coverOption)].url;f.elements.capa.value=chosen;o.querySelector('#itemCoverPreview').src=await api.coverImage(chosen);picker.remove();toast('Capa selecionada. Salve para aplicar.')})}catch(err){f.querySelector('.form-error').textContent=failure(err)}finally{btn.disabled=false}});f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button.primary'),data=Object.fromEntries(new FormData(f));data.categoria=info.category;if(item)data.id=String(item.id);for(const k of ['ano','horas','conquistas','tempo_est','preco','steam_appid'])if(k in data){const original=row[k],untouchedText=data[k]===''&&original!=null&&original!==''&&!Number.isFinite(Number(original))&&!f.elements[k]?.dataset.numericTouched;data[k]=untouchedText?original:data[k]===''?null:Number(data[k])}if(data.nota==='Sem avaliação')data.nota=null;if(!data.data)data.data=null;if('inicio' in data&&!data.inicio)data.inicio=null;b.disabled=true;try{const saved=await api.saveItem(data),updated={...row,...data,...(Array.isArray(saved)?saved[0]||{}:{})};f.dataset.saved='1';close();toast('Título salvo.');if(!item||!window.batcavernaRefreshLibraryItem?.(updated)){if(state.current==='home')await renderHome();else await renderLibrary()}}catch(err){const message=failure(err),error=f.querySelector('.form-error');error.textContent=message;b.disabled=false;if(/já está na sua biblioteca|itens_steam_unico/i.test(message)&&data.steam_appid){const rows=await api.library('jogos').catch(()=>[]);if(!f.isConnected)return;const existing=rows.find(x=>Number(x.steam_appid)===Number(data.steam_appid)&&String(x.id)!==String(data.id));if(existing){const open=document.createElement('button');open.type='button';open.className='secondary';open.textContent='Abrir jogo já cadastrado';open.onclick=()=>{close();openItemEditor(existing)};error.append(document.createElement('br'),open)}}}};o.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!await window.batcavernaConfirm(`Excluir “${row.nome}”?`,"Esta ação remove o título da sua biblioteca."))return;try{await api.deleteItem(row.id);close();await renderLibrary()}catch(e){toast(failure(e))}})}
function catalogTitleKey(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[™®]/g,'').replace(/[^a-z0-9]+/g,' ').trim();}
function matchCatalogTitle(rows,item){const key=catalogTitleKey(item.nome),year=String(item.ano||'');const matches=(rows||[]).filter(x=>[x.name,typeof x.title==='string'?x.title:x.title?.english,x.title?.romaji,x.title?.native].some(v=>catalogTitleKey(v)===key));if(year){const dated=matches.filter(x=>String(x.released||x.release_date||x.first_air_date||x.startDate?.year||'').slice(0,4)===year);if(dated.length===1)return dated[0];}return matches.length===1?matches[0]:null;}
async function searchCatalog(f,info,page=1){const btn=f.querySelector('#catalogSearch'),msg=f.querySelector('#catalogMessage'),out=f.querySelector('#catalogResults'),q=f.querySelector('#catalogQuery').value.trim(),game=info.category==='jogos',provider=game?'igdb':info.type==='anime'?f.querySelector('#animeProvider').value:'tmdb',kind=info.type==='filme'?'movie':'tv';if(q.length<2){msg.textContent='Digite pelo menos dois caracteres.';return}btn.disabled=true;msg.textContent='Buscando…';out.innerHTML='';try{const generation=(f.catalogGeneration||0)+1;f.catalogGeneration=generation;const d=await api.catalog({provider,kind,query:q,page});if(generation!==f.catalogGeneration)return;if(!f.isConnected)return;let rows=provider==='anilist'?(d.data?.Page?.media||[]).filter(x=>x.isAdult===false&&!/hentai|ecchi/i.test((x.genres||[]).join(' '))):(d.results||[]).filter(x=>!x.adult);if(d.errors)throw Error('Não foi possível consultar o AniList.');msg.textContent=rows.length?'Selecione um resultado para preencher os dados.':'Nenhum título encontrado.';out.innerHTML=rows.map((x,i)=>{const title=provider==='igdb'?x.name:provider==='anilist'?x.title.english||x.title.romaji:x.title||x.name,cover=provider==='igdb'?(f.querySelector('#coverOrientation')?.value==='landscape'?x.background_image:x.cover_image||x.background_image):provider==='anilist'?x.coverImage?.large:x.poster_path?'https://image.tmdb.org/t/p/w185'+x.poster_path:'';return `<button type="button" data-result="${i}"><img src="${validImage(cover)}" alt=""><span>${esc(title)}<small>${esc(x.released||x.release_date||x.first_air_date||x.startDate?.year||'')}</small></span></button>`}).join('');const pages=Math.min(100,d.total_pages||Math.ceil((d.count||0)/40)||d.data?.Page?.pageInfo?.lastPage||1);out.insertAdjacentHTML('beforeend',`<div class="catalog-pagination"><button type="button" data-page="${page-1}" ${page<=1?'disabled':''}>Anterior</button><span>Página ${page}</span><button type="button" data-page="${page+1}" ${page>=pages?'disabled':''}>Mais resultados</button></div>`);out.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>searchCatalog(f,info,Number(b.dataset.page)));out.querySelectorAll('[data-result]').forEach(b=>b.onclick=async()=>{out.querySelectorAll('button').forEach(x=>x.disabled=true);msg.textContent='Carregando detalhes…';try{let x=rows[Number(b.dataset.result)],providers=[];if(provider==='igdb')x=await api.catalog({provider,id:x.id});if(provider==='tmdb'){const all=await Promise.all([api.catalog({provider,kind,id:x.id}),api.catalog({provider,kind,id:x.id,providers:true}).catch(()=>null)]);x=all[0];providers=all[1]?.results?.BR?.flatrate||[];}if(!f.isConnected)return;if(game&&f.elements.steam_appid)f.elements.steam_appid.value='';f.elements.nome.value=provider==='anilist'?x.title.english||x.title.romaji:x.name||x.title||'';f.elements.ano.value=String(x.released||x.release_date||x.first_air_date||x.startDate?.year||'').slice(0,4);f.elements.generos.value=(x.genres||[]).map(g=>typeof g==='string'?g:g.name).join(' • ');let cover=provider==='igdb'?(f.querySelector('#coverOrientation')?.value==='landscape'?x.background_image:x.cover_image||x.background_image):provider==='anilist'?(f.querySelector('#coverOrientation')?.value==='landscape'?x.bannerImage||x.coverImage?.large:x.coverImage?.large):f.querySelector('#coverOrientation')?.value==='landscape'&&x.backdrop_path?'https://image.tmdb.org/t/p/w1280'+x.backdrop_path:x.poster_path?'https://image.tmdb.org/t/p/w500'+x.poster_path:'';if(game){f.elements.plataforma.value='💻 PC';const stores=(x.stores||[]).map(z=>z.store.name);const store=stores.includes('Steam')?'Steam':stores.find(z=>[...f.elements.loja.options].some(o=>o.value===z));if(store)f.elements.loja.value=store;if(!cover){try{const sg=await api.bright({op:'capas',nomes:[f.elements.nome.value],format:f.querySelector('#coverOrientation')?.value||document.body.dataset.cardFormat||'poster'});if(sg.capas?.[0])cover=sg.capas[0]}catch{}}}else if(providers.length){const names=providers.map(z=>z.provider_name),first=names[0];f.elements.onde.innerHTML=selectOptions([...names,...[...f.elements.onde.options].map(z=>z.value)],first)}f.elements.capa.value=cover||'';f.querySelector('#itemCoverPreview').src=validImage(cover);window.batcavernaRenderDescription(f.querySelector('#catalogDescription'),x.description_raw||x.overview||x.description||'',1800);msg.textContent='Dados preenchidos. Confira o status, sua nota e as horas antes de salvar.'}catch(err){msg.textContent=failure(err)}finally{out.querySelectorAll('button').forEach(x=>x.disabled=false)}})}catch(err){msg.textContent=failure(err)}finally{btn.disabled=false}}

async function renderDiscover(){setPage('Grátis & Steam','DESCOBRIR');$('#content').innerHTML=`<div class="tabs"><button data-discover="free" class="${state.discoverTab==='free'?'active':''}">Jogos grátis</button><button data-discover="steam" class="${state.discoverTab==='steam'?'active':''}">Minha Steam</button></div><div id="discoverBody"><div class="loading"><span class="spinner"></span>Buscando…</div></div>`;$$('[data-discover]').forEach(b=>b.onclick=()=>{state.discoverTab=b.dataset.discover;renderDiscover()});const out=$('#discoverBody');if(state.discoverTab==='free'){const d=await api.bright({op:'gratis'});const rows=[...(d.epic||[]).map(x=>({...x,store:'Epic'})),...(d.steam||[]).map(x=>({...x,store:'Steam'}))];out.innerHTML=`<div class="section-head"><div><h2>Ofertas 100% grátis</h2><p>Itens disponíveis para resgate nas lojas.</p></div></div><section class="offers">${rows.map(offerCard).join('')||'<div class="empty">Nenhuma oferta encontrada agora.</div>'}</section>`}else{const profile=await api.profile(null),sid=profile?.steam_id;if(!sid){out.innerHTML='<div class="empty">Conecte seu perfil Steam em Configurações para ver sua biblioteca.</div>';return}const d=await api.bright({op:'jogos',steamid:String(sid)});out.innerHTML=`<div class="section-head"><div><h2>Biblioteca Steam</h2><p>${(d.jogos||[]).length} jogos encontrados</p></div></div><section class="offers">${(d.jogos||[]).sort((a,b)=>(b.horas||0)-(a.horas||0)).map(g=>offerCard({...g,capa:`https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/${g.appid}/header.jpg`,url:`https://store.steampowered.com/app/${g.appid}`,store:`${g.horas||0}h`})).join('')}</section>`}$$('[data-open-url]').forEach(b=>b.onclick=()=>api.open(b.dataset.openUrl))}
function offerCard(x){const cover=coverUrl(x.capa);return `<article class="offer-card"><img src="brand.jpg" data-cover="${esc(cover)}" data-cover-name="${esc(x.nome)}" data-cover-game="1" ${cover?'':'data-auto-format="1"'} data-cover-format="${document.body.dataset.cardFormat||'poster'}" data-steam-appid="${esc(x.appid||x.steamAppid||String(x.url||'').match(/app\/(\d+)/)?.[1]||'')}" alt="Capa de ${esc(x.nome)}"><div class="body"><h3>${esc(x.nome)}</h3><footer><small>${esc([x.store||'Grátis',x.tipo].filter(Boolean).join(' · '))}</small><button class="secondary" data-open-url="${esc(x.url||'')}">Resgatar</button></footer></div></article>`}

function feedMedia(urls){return urls?.length?`<div class="feed-media">${urls.map((u,i)=>/\.(mp4|webm)(?:\?|$)/i.test(u)?`<video controls preload="metadata" data-private-src="${esc(u)}"></video>`:`<img loading="lazy" tabindex="0" role="button" aria-label="Ampliar imagem" data-private-src="${esc(u)}" alt="Mídia da publicação ${i+1}">`).join('')}</div>`:''}
async function renderSocial(){setPage('Social','COMUNIDADE');const [posts,meta]=await Promise.all([api.feed(),api.socialMeta()]),likes={},mine={},comments={};if(state.current!=='social')return;(meta.likes||[]).forEach(x=>{likes[x.post_id]=(likes[x.post_id]||0)+1;if(String(x.user_id)===String(meta.userId))mine[x.post_id]=true});(meta.comments||[]).forEach(x=>(comments[x.post_id]||(comments[x.post_id]=[])).push(x));$('#content').innerHTML=`<form id="composer" class="composer"><textarea name="text" maxlength="2000" placeholder="Compartilhe algo com a comunidade"></textarea><div id="mediaPreview" class="media-preview"></div><footer><div class="composer-tools"><label class="file-button">＋ Foto ou vídeo<input id="postFiles" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm" multiple></label><small class="muted">Até 4 arquivos</small></div><button class="primary">Publicar</button></footer></form><section class="posts">${posts.map(p=>{const id=String(p.id),cs=comments[id]||[];return `<article class="post" data-post="${esc(id)}" data-post-author="${esc(p.user_id)}"><header><img data-private-src="${esc(p.author?.avatar_url||'')}" src="brand.jpg" alt=""><div><strong>${esc(p.author?.nome||'BatCaverna')}</strong><br><time>${date(p.created_at)}</time></div></header><p>${esc(p.texto)}</p>${feedMedia(p.midias||[])}<div class="post-actions"><button data-like class="${mine[id]?'liked':''}">♥ ${likes[id]||0}</button><span>💬 ${cs.length}</span></div>${cs.slice(-3).map(c=>`<div class="comment"><strong>${String(c.user_id)===String(meta.userId)?'Você':'Amigo'}</strong> ${esc(c.texto)}</div>`).join('')}<form data-comment><input name="text" maxlength="500" placeholder="Escreva um comentário"><button>Enviar</button></form></article>`}).join('')||'<div class="empty">Ainda não há publicações.</div>'}</section>`;await hydrateMedia($('#content'));const key='bc-desktop-draft:'+state.userId,ta=$('#composer textarea');ta.value=localStorage.getItem(key)||'';ta.oninput=()=>localStorage.setItem(key,ta.value);$('#postFiles').onchange=e=>previewFiles([...e.target.files].slice(0,4));$('#composer').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('.primary'),sent=ta.value;b.disabled=true;b.textContent=state.uploadFiles.length?'Enviando mídia…':'Publicando…';try{const media=[];for(const file of state.uploadFiles)media.push(await uploadFile(file));await api.publish({text:sent,media});state.uploadFiles=[];if(localStorage.getItem(key)===sent)localStorage.removeItem(key);toast('Publicação enviada.');await renderSocial()}catch(err){toast(failure(err));b.disabled=false;b.textContent='Publicar'}};$$('[data-post]').forEach(a=>{const postId=a.dataset.post;a.querySelector('[data-like]').onclick=async e=>{e.currentTarget.disabled=true;try{await api.toggleLike({postId,liked:e.currentTarget.classList.contains('liked')});await renderSocial()}catch(err){toast(failure(err))}};a.querySelector('[data-comment]').onsubmit=async e=>{e.preventDefault();try{await api.addComment({postId,text:e.currentTarget.elements.text.value});await renderSocial()}catch(err){toast(failure(err))}}})}
function previewFiles(files){state.uploadFiles=files.filter(f=>/^(image\/(png|jpeg|webp)|video\/(mp4|webm))$/.test(f.type));const box=$('#mediaPreview');box.innerHTML=state.uploadFiles.map((f,i)=>{const u=URL.createObjectURL(f);return `<div>${f.type.startsWith('video/')?`<video src="${u}"></video>`:`<img src="${u}" alt="">`}<small>${esc(f.name)}</small></div>`}).join('')}
function uploadFile(file){if(file.size>12*1024*1024)return Promise.reject('Cada arquivo deve ter no máximo 12 MB.');return new Promise((ok,no)=>{const r=new FileReader();r.onerror=()=>no('Não foi possível ler o arquivo.');r.onload=()=>api.uploadMedia({name:file.name,mime:file.type,base64:String(r.result).split(',')[1]}).then(x=>ok(x.url)).catch(no);r.readAsDataURL(file)})}

async function renderChat(){setPage('Chat','CONVERSAS');const friends=await api.friends();if(!state.chatFriend&&friends.length)state.chatFriend=friends[0];const active=state.chatFriend,messages=active?await api.messages(String(active.id)):[];$('#content').innerHTML=`<section class="chat-layout"><aside class="chat-people"><h3>Conversas</h3>${friends.map(p=>`<button data-chat-user="${esc(p.id)}" class="${active&&String(active.id)===String(p.id)?'active':''}"><img data-private-src="${esc(p.avatar_url||'')}" src="brand.jpg" alt=""><span><strong>${esc(p.nome||p.slug||'Amigo')}</strong><small>@${esc(p.slug||'batcaverna')}</small></span></button>`).join('')||'<div class="empty">Adicione amigos para conversar.</div>'}</aside><div class="conversation">${active?`<header><img data-private-src="${esc(active.avatar_url||'')}" src="brand.jpg" alt=""><div><strong>${esc(active.nome||active.slug)}</strong><small>Conversa privada</small></div></header><div class="messages">${messages.map(m=>`<div class="message ${String(m.remetente_id)===String(state.userId)?'mine':''}">${m.midia_url?`<img data-private-src="${esc(m.midia_url)}" src="brand.jpg" alt="Imagem" style="max-width:280px;border-radius:8px">`:''}<p>${esc(m.texto||'')}</p><time>${date(m.created_at)}</time></div>`).join('')||'<div class="chat-empty">Comece a conversa.</div>'}</div><form id="messageForm"><textarea name="text" maxlength="2000" placeholder="Escreva uma mensagem"></textarea><button class="primary">Enviar</button></form>`:'<div class="chat-empty">Selecione uma conversa.</div>'}</div></section>`;await hydrateMedia($('#content'));$$('[data-chat-user]').forEach(b=>b.onclick=()=>{state.chatFriend=friends.find(p=>String(p.id)===b.dataset.chatUser);renderChat().catch(errorCard)});$('#messageForm')?.addEventListener('submit',async e=>{e.preventDefault();const text=e.currentTarget.elements.text.value;if(!text.trim())return;const b=e.currentTarget.querySelector('button');b.disabled=true;try{await api.sendMessage({friendId:String(active.id),text});await renderChat()}catch(err){toast(failure(err));b.disabled=false}});const box=$('.messages');if(box)box.scrollTop=box.scrollHeight}

function personCard(p,mode='friend'){return `<article class="person"><img data-private-src="${esc(p.avatar_url||'')}" src="brand.jpg" alt=""><div><strong>${esc(p.nome||p.slug||'Perfil')}</strong><small>@${esc(p.slug||'batcaverna')}</small></div><button class="secondary" data-profile-user="${esc(p.id)}">Perfil</button>${mode==='friend'?`<button class="secondary" data-open-chat="${esc(p.id)}">Chat</button>`:`<button class="primary" data-invite="${esc(p.id)}">Convidar</button>`}</article>`}
async function renderFriends(){setPage('Amigos','COMUNIDADE');const rows=await api.friends();$('#content').innerHTML=`<form id="peopleSearch" class="search-people"><input name="query" minlength="2" placeholder="Buscar por usuário, nome ou código"><button class="primary">Buscar</button></form><div id="peopleResults"></div><div class="section-head"><div><h2>Seus amigos</h2><p>${rows.length} conexões</p></div></div><section class="people">${rows.map(p=>personCard(p)).join('')||'<div class="empty">Sua lista de amigos está vazia.</div>'}</section>`;await hydrateMedia($('#content'));wirePeople(rows);$('#peopleSearch').onsubmit=async e=>{e.preventDefault();const out=$('#peopleResults');out.innerHTML='<div class="loading">Buscando…</div>';try{const found=await api.searchPeople(e.currentTarget.elements.query.value);out.innerHTML=`<section class="people">${found.map(p=>personCard(p,'search')).join('')||'<div class="empty">Nenhuma pessoa encontrada.</div>'}</section>`;await hydrateMedia(out);wirePeople(found);out.querySelectorAll('[data-invite]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api.invite(b.dataset.invite);b.textContent='Enviado'}catch(err){toast(failure(err));b.disabled=false}})}catch(err){out.innerHTML=`<div class="error-card">${esc(failure(err))}</div>`}}}
