function confirmUpdate(update){
 const version=String(update.version||'').trim();
 if(!version)throw Error('A verificação retornou uma versão inválida.');
 const notes=String(update.notes||'').trim();
 const modal=window.batcavernaPopup(`<header><div><span class="eyebrow">BATCAVERNA PARA WINDOWS</span><h2>Atualização disponível</h2></div><button class="icon-button" type="button" aria-label="Fechar" data-update-cancel>×</button></header><div class="update-release-notes"><strong>Versão ${esc(version)}</strong><p>${esc(notes||'Esta versão inclui melhorias e correções.')}</p></div><p class="muted">O instalador verificará a assinatura antes de aplicar a atualização.</p><footer><button class="secondary" type="button" data-update-cancel>Agora não</button><button class="primary" type="button" data-update-install>Baixar e instalar</button></footer>`,'update-confirm-modal');
 modal.classList.add('update-confirm-overlay');
 modal.setAttribute('role','presentation');
 const dialog=modal.querySelector('.update-confirm-modal');
 dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-labelledby','updateDialogTitle');
 dialog.querySelector('h2').id='updateDialogTitle';
 return new Promise(resolve=>{
  let settled=false;
  const finish=accepted=>{if(settled)return;settled=true;modal.remove();resolve(accepted)};
  modal.onclick=event=>{if(event.target===modal)finish(false)};
  modal.querySelectorAll('[data-update-cancel]').forEach(button=>button.onclick=()=>finish(false));
  modal.querySelector('[data-update-install]').onclick=()=>finish(true);
  dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();finish(false)}});
  modal.querySelector('[data-update-cancel]').focus();
 });
}
async function checkForUpdates(){const button=$('#checkUpdates'),status=$('#updateStatus');if(!button||!status)return;button.disabled=true;status.textContent='Consultando versões…';try{const update=await api.checkForUpdates();if(!status.isConnected)return;if(!update.available){status.textContent='Você já está usando a versão mais recente.';return}if(!await confirmUpdate(update)){if(status.isConnected)status.textContent=`Atualização ${esc(update.version)} disponível para instalar quando desejar.`;return}status.textContent=`Baixando e verificando a assinatura da versão ${esc(update.version)}…`;await api.installUpdate(update.version);if(status.isConnected)status.textContent='Atualização instalada. O instalador iniciará a versão nova.'}catch(error){if(status.isConnected)status.textContent=`Não foi possível verificar ou instalar atualizações: ${failure(error)}`}finally{if(button.isConnected)button.disabled=false}}
function openPassword(){const o=document.createElement('div');o.className='editor-overlay';o.innerHTML=`<form class="editor" style="max-width:460px"><header><h2>Alterar senha</h2><button type="button" class="icon-button" data-close>×</button></header><div class="editor-grid"><label class="wide">Senha atual<input name="current" type="password" required></label><label class="wide">Nova senha<input name="password" type="password" minlength="12" required></label><label class="wide">Confirmar<input name="confirm" type="password" minlength="12" required></label></div><footer><span></span><button class="primary">Salvar</button></footer><p class="form-error"></p></form>`;document.body.appendChild(o);const close=()=>o.remove();o.querySelector('[data-close]').onclick=close;o.querySelector('form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(d.password!==d.confirm){e.currentTarget.querySelector('.form-error').textContent='As senhas devem coincidir.';return}try{await api.changePassword({current:d.current,password:d.password});close();toast('Senha atualizada.')}catch(err){e.currentTarget.querySelector('.form-error').textContent=failure(err)}}}

