$('#loginForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,err=$('#loginError'),d=new FormData(form),b=form.querySelector('.primary');err.textContent='';b.disabled=true;b.textContent='Entrando…';try{await api.login({identifier:String(d.get('identifier')||'').trim(),password:String(d.get('password')||''),remember:d.get('remember')==='on'});showApp()}catch(failure){err.textContent=failureMessage(failure)}finally{b.disabled=false;b.textContent=b.dataset.idleLabel}};
function openEmailProof(recovery,email=''){
 const o=document.createElement('div');o.className='editor-overlay';
 o.innerHTML=`<form class="editor" style="max-width:520px"><header><h2>${recovery?'Definir nova senha':'Confirmar cadastro'}</h2><button type="button" class="icon-button" data-close aria-label="Fechar">×</button></header><div class="editor-grid"><label class="wide">E-mail da conta<input name="email" type="email" value="${esc(email)}" required autocomplete="email"></label><p class="wide muted">Digite o código recebido. Se o e-mail tiver apenas um botão, copie o link dele e cole abaixo, sem abri-lo.</p><label class="wide">Código ou link recebido<input name="proof" required maxlength="4096" autocomplete="one-time-code"></label>${recovery?'<label class="wide">Nova senha<input name="password" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></label><label class="wide">Confirmar nova senha<input name="confirm" type="password" minlength="12" maxlength="256" required autocomplete="new-password"></label>':''}</div><footer>${recovery?'':'<button type="button" class="secondary" data-resend>Reenviar confirmação</button>'}<button class="primary">${recovery?'Salvar nova senha':'Confirmar e-mail'}</button></footer><p class="form-error" role="status" aria-live="polite"></p></form>`;
 document.body.appendChild(o);const f=o.querySelector('form'),msg=f.querySelector('.form-error');let busy=false;
 o.querySelector('[data-close]').onclick=()=>{if(!busy){f.reset();o.remove()}};
 const resend=o.querySelector('[data-resend]');if(resend)resend.onclick=async()=>{if(busy||!f.elements.email.reportValidity())return;busy=true;resend.disabled=true;f.querySelector('.primary').disabled=true;try{await api.resendConfirmation(f.elements.email.value);msg.textContent='Se houver confirmação pendente, um novo e-mail será enviado.'}catch(e){msg.textContent=failure(e)}busy=false;f.querySelector('.primary').disabled=false;setTimeout(()=>{if(resend.isConnected&&!busy)resend.disabled=false},60000)};
 f.onsubmit=async e=>{e.preventDefault();if(busy)return;const d=Object.fromEntries(new FormData(f));if(recovery&&d.password!==d.confirm){msg.textContent='As senhas devem coincidir.';return}busy=true;const controls=[...f.querySelectorAll('input,button')];controls.forEach(x=>x.disabled=true);msg.textContent='Verificando…';try{const r=await api.verifyEmail({email:d.email,proof:d.proof,recovery,password:recovery?d.password:null});f.reset();o.remove();setAuth('login');toast(r.message)}catch(error){msg.textContent=failure(error);f.elements.proof.value='';if(recovery){f.elements.password.value='';f.elements.confirm.value=''}}finally{busy=false;controls.forEach(x=>x.disabled=false)}};
}
$$('[data-email-proof]').forEach(b=>b.onclick=()=>openEmailProof(b.dataset.emailProof==='recovery'));
$('#registerForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.primary'),err=f.querySelector('.error'),d=Object.fromEntries(new FormData(f));b.disabled=true;try{const r=await api.register(d);f.reset();if(r.confirmationRequired===false){setAuth('login');toast(r.message||'Conta criada. Você já pode entrar.')}else openEmailProof(false,d.email)}catch(x){err.textContent=failure(x)}finally{b.disabled=false}};
$('#recoverForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.primary'),err=f.querySelector('.error');b.disabled=true;try{const email=f.elements.email.value;await api.recover(email);openEmailProof(true,email)}catch(x){err.textContent=failure(x)}finally{b.disabled=false}};
applyPrefs();let appInitialized=false;const initializeApp=()=>{if(appInitialized)return;appInitialized=true;api.state().then(s=>{state.version=s.version;state.userId=s.user?.id||'';state.email=s.user?.email||'';s.authenticated?showApp():showLogin()}).catch(error=>{showLogin();$('#loginError').textContent=failureMessage(error)})};window.addEventListener('batcaverna:legacy-ready',initializeApp,{once:true});

function catalogDescriptionText(value){
 const decoder=document.createElement('textarea');let text=String(value||'');
 for(let pass=0;pass<2;pass++){const next=text.replace(/&(?:#[0-9]+|#x[0-9a-f]+|[a-z][a-z0-9]+);/gi,entity=>{decoder.innerHTML=entity;return decoder.value});if(next===text)break;text=next;}
 return text.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi,'').replace(/<br\s*\/?\s*>|<\/(?:p|div|li|h[1-6])\s*>/gi,'\n').replace(/<[^>]*>/g,'').replace(/\u00a0/g,' ').trim();
}
function detailedPlaytime(value){
 if(value==null||String(value).trim()==='')return 'Sem tempo registrado';const hours=Number(String(value).replace(',','.'));if(!Number.isFinite(hours)||hours<0)return 'Sem tempo registrado';
 if(hours>0&&hours*60<1)return 'Menos de 1 min';const minutes=Math.round(hours*60),h=Math.floor(minutes/60),m=minutes%60;
 return h?`${h.toLocaleString('pt-BR')} h${m?` ${m} min`:''}`:`${m} min`;
}
function playtimeBadge(value){const hours=Number(String(value??'').replace(',','.'));if(!Number.isFinite(hours)||hours<=0)return '';return `<span class="playtime-badge" aria-label="Tempo jogado: ${esc(detailedPlaytime(value))}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg><span><strong>${esc(detailedPlaytime(value))}</strong><small>TEMPO JOGADO</small></span></span>`;}
// Attribution travels with the translated description, including for older clients.
window.batcavernaRenderDescription=function(node,value,limit=0){
 const notice='\n\nTradução automática por DeepL.com — https://www.deepl.com',source=catalogDescriptionText(value),translated=source.endsWith(notice),body=translated?source.slice(0,-notice.length):source;
 node.textContent=limit?body.slice(0,limit):body;
 if(node.nextElementSibling?.hasAttribute('data-translation-credit'))node.nextElementSibling.remove();
 if(translated){const credit=document.createElement('p');credit.className='muted';credit.setAttribute('data-translation-credit','');credit.append('Tradução automática por ');const link=document.createElement('button');link.type='button';link.className='link-button';link.textContent='DeepL.com';link.onclick=()=>api.open('https://www.deepl.com');credit.append(link);node.after(credit);}
};
